const json = pm.response.json();
pm.test('Status is 200', () => pm.response.to.have.status(200));
pm.test('resourceType is Bundle', () => pm.expect(json.resourceType).to.eql('Bundle'));
const entries = json.entry || [];
console.log('Rows returned: ' + entries.length);
if (entries.length > 0) {
  const wm = new Date(pm.variables.get('watermark')).getTime();
  const dates = entries.map(e => new Date(e.resource.meta.lastUpdated).getTime());
  pm.test('All records are newer than watermark', () => dates.forEach(d => pm.expect(d).to.be.above(wm)));
  pm.test('Sorted ascending by lastUpdated', () => {
    for (let i = 1; i < dates.length; i++) pm.expect(dates[i]).to.be.at.least(dates[i-1]);
  });
  const maxLu = entries[entries.length - 1].resource.meta.lastUpdated;
  pm.environment.set('newWatermark', maxLu);
  console.log('Candidate new watermark: ' + maxLu);
} else {
  pm.test('Empty result is valid (no new data)', () => pm.expect(entries.length).to.eql(0));
}
